// Code generated by `cargo run -p codegen` — DO NOT EDIT
// Quantity: RelativeHumidity

#![cfg(feature = "misc")]
#![allow(
    clippy::excessive_precision,
    clippy::unreadable_literal,
    clippy::double_parens,
    unused_parens
)]

use super::{assert_close, check_fixed, check_fixed_rescale, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use unitsnet_rs::*;

#[test]
fn percent() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(RelativeHumidity::from_percent(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x;
        assert_close(
            RelativeHumidity::from_base(base).as_percent(),
            back,
            F64_TOL,
        );
        assert_close(
            RelativeHumidity::from_percent(v).as_percent(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            RelativeHumidity::from_percent(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            RelativeHumidity::from_base(base as f32).as_percent() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn fixed_units() {
    check_fixed::<unit::relative_humidity::Percent>();
    check_fixed_rescale::<unit::relative_humidity::Percent>();
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        RelativeHumidity::new(v, RelativeHumidityUnit::Percent),
        RelativeHumidity::from_percent(v)
    );
    assert_eq!(
        RelativeHumidity::from_base(v).convert_to(RelativeHumidityUnit::Percent),
        RelativeHumidity::from_base(v).as_percent()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = RelativeHumidity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            RelativeHumidity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in RelativeHumidityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        RelativeHumidity::from_base(0.0).auto_unit().unit,
        RelativeHumidityUnit::Percent
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "%RH".parse::<RelativeHumidityUnit>(),
        Ok(RelativeHumidityUnit::Percent)
    );
    assert_eq!(
        format!("2.5 {}", "%RH").parse::<RelativeHumidity>(),
        Ok(RelativeHumidity::new(2.5, RelativeHumidityUnit::Percent))
    );
    assert_eq!(
        "1 not-a-unit".parse::<RelativeHumidity>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn parse_every_name() {
    assert_eq!(
        RelativeHumidityUnit::from_name("percent"),
        Some(RelativeHumidityUnit::Percent)
    );
    assert_eq!(
        RelativeHumidityUnit::from_name("percent"),
        Some(RelativeHumidityUnit::Percent)
    );
    assert_eq!(
        RelativeHumidityUnit::from_name("PERCENT"),
        Some(RelativeHumidityUnit::Percent)
    );
    assert_eq!(
        RelativeHumidityUnit::from_name("percent"),
        Some(RelativeHumidityUnit::Percent)
    );
    assert_eq!(
        RelativeHumidityUnit::from_name("percent"),
        Some(RelativeHumidityUnit::Percent)
    );
    assert_eq!(
        RelativeHumidityUnit::from_name("PERCENT"),
        Some(RelativeHumidityUnit::Percent)
    );
}

#[test]
fn arithmetic_f64() {
    let a = RelativeHumidity::from_base(6.0);
    let b = RelativeHumidity::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = RelativeHumidity::<i64>::from_base(7);
    let b = RelativeHumidity::<i64>::from_base(2);
    assert_eq!(a + b, RelativeHumidity::from_base(9));
    assert_eq!(a % b, RelativeHumidity::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<RelativeHumidity<i64>>(),
        RelativeHumidity::from_base(9)
    );
}
